import {initialState,legalTurns,applyTurn,stepBoard,portalPair,coord,notation,outcome,chooseMove} from './engine.js';
import {BoardView} from './scene.js';
const $=s=>document.querySelector(s);
import {icons,iconMarkup} from './icons.js';
icons();
const formatMove=move=>notation(move).replaceAll(' ◇ ',' / ');
let state=initialState(),mode='ai',level='normal',selected=null,choices=[],stepIndex=0,turnStart=null,busy=false,epoch=0,worker=null,history=[],last=[],hinting=false,view,workerCancel=null;
let prefs={sound:false,motion:matchMedia('(prefers-reduced-motion: reduce)').matches,low:false};try{prefs={...prefs,...JSON.parse(localStorage.getItem('eclipse-preferences')||'{}')};}catch{}
const savePrefs=()=>{try{localStorage.setItem('eclipse-preferences',JSON.stringify(prefs));}catch{}};
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3300);}
let audio;function sound(type='move'){if(!prefs.sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const t=audio.currentTime;const notes=type==='portal'?[330,495,660]:type==='capture'?[180,270]:type==='win'?[330,440,550,660]:[260,390];notes.forEach((f,i)=>{const osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.setValueAtTime(f,t+i*.055);gain.gain.setValueAtTime(.001,t+i*.055);gain.gain.exponentialRampToValueAtTime(.08,t+i*.055+.01);gain.gain.exponentialRampToValueAtTime(.001,t+i*.055+.3);osc.connect(gain);gain.connect(audio.destination);osc.start(t+i*.055);osc.stop(t+i*.055+.31);});}catch{}}
const humanTurn=()=>mode==='local'||state.turn===1;
const visibleSteps=()=>choices.map(m=>m.steps[stepIndex]).filter(Boolean);
function setText(sel,text){$(sel).textContent=text;}
function render(){
 const pair=portalPair(state),ended=outcomeForUI();view?.sync(state.board,pair);view?.highlight(selected,visibleSteps(),last);
 const white=state.board.filter(p=>p>0).length,black=state.board.filter(p=>p<0).length;
 for(const [side,count] of [['white',white],['black',black]]){$(`#${side}-count`).innerHTML=`${count}<span>na planszy</span>`;$(`.${side}-mini`).innerHTML=Array.from({length:12},(_,i)=>`<i class="${i>=count?'gone':''}"></i>`).join('');$(`#${side}-player`).classList.toggle('active',!ended&&state.turn===(side==='white'?1:-1));}
 setText('#round-label',`RUNDA ${String(Math.floor(state.ply/2)+1).padStart(2,'0')}`);setText('#mode-caption',mode==='ai'?'KOMPUTER':'DWIE OSOBY');setText('#black-name',mode==='ai'?'Nox':'Czarne');setText('#white-name',mode==='ai'?'Ty':'Białe');setText('#black-caption',mode==='ai'?`Komputer · ${{easy:'Odkrywca',normal:'Taktyk',hard:'Strateg'}[level]}`:'Gracz 2');
 $('#turn-dot').classList.toggle('dark',state.turn===-1);
 let title=humanTurn()?(mode==='ai'?'Twój ruch':state.turn===1?'Ruch białych':'Ruch czarnych'):'Ruch przeciwnika';
 let help=selected===null?`Wybierz ${state.turn===1?'jasny':'ciemny'} pion`:'Wybierz podświetlone pole';
 if(!humanTurn())help='Nox wybiera posunięcie';else if(stepIndex>0){title='Kontynuuj bicie';help='Ten sam pion ma kolejne bicie';}else if(legalTurns(state)[0]?.captures){help=selected===null?'Masz bicie — wybierz pion, który może bić':'Bicie jest obowiązkowe';}
 if(ended){title=ended.winner===0?'Remis':ended.winner===1?'Białe wygrywają':'Czarne wygrywają';help='Partia zakończona';}
 setText('#turn-title',title);setText('#turn-help',help);
 $('#undo-btn').disabled=busy&&!worker||(!history.length&&!turnStart);$('#hint-btn').disabled=busy||!humanTurn()||!!ended||stepIndex>0||hinting;
 const eclipse=state.variant==='eclipse';$('#variant-title').innerHTML=eclipse?'Warcaby<br><em>Eclipse.</em>':'Warcaby<br><em>klasyczne.</em>';$('#variant-copy').innerHTML=eclipse?'Dwanaście pionów.<br>O jedną drogę więcej.':'Dwanaście pionów.<br>Cała siła w posunięciu.';
 $('#variant-badge').innerHTML=`<span class="icon">${iconMarkup(eclipse?'portal':'board')}</span>${eclipse?'WARIANT Z PORTALAMI':'WARIANT BEZ PORTALI'}`;
 setText('#white-caption',mode==='ai'?'Grasz białymi':'Gracz 1');
 setText('#portal-title',eclipse?'Połączone pola':'Plansza 8 × 8');setText('#portal-a',eclipse?coord(pair[0]):'12');setText('#portal-b',eclipse?coord(pair[1]):'12');setText('.route-line',eclipse?'↔':':');
 $('#portal-map').innerHTML=Array.from({length:64},(_,i)=>`<i class="${((i>>3)+i%8)%2?'dark':''} ${pair[0]===i?'gate-a':pair[1]===i?'gate-b':''}"></i>`).join('');$('#portal-map').setAttribute('aria-label',eclipse?`Portale na polach ${coord(pair[0])} i ${coord(pair[1])}`:'Plansza warcabowa, osiem na osiem pól');$('.portal-map-caption').innerHTML=eclipse?'AKTYWNE<br>POLA':'BIAŁE<br>I CZARNE';
 setText('#portal-desc',eclipse?'Ruch na oznaczone pole przenosi pion do drugiego portalu.':'Piony poruszają się po ciemnych polach. Białe zaczynają.');
 const remaining=8-state.ply%8;setText('#mobile-portals',eclipse?`Portale: ${coord(pair[0])} / ${coord(pair[1])} · ${remaining} tur do zmiany`:'Warcaby klasyczne · bez portali');
 setText('#phase-caption',eclipse?`Zmiana pól za ${Math.ceil(remaining/2)} ${Math.ceil(remaining/2)===1?'rundę':'rundy'}`:'Po 12 pionów na stronę');
 document.querySelectorAll('.phase-bars i').forEach((el,i)=>{el.classList.toggle('done',i<Math.floor((state.ply%8)/2));el.classList.toggle('current',i===Math.floor((state.ply%8)/2));});$('.phase-bars').hidden=!eclipse;

 $('.rule-note span:last-child').innerHTML='Bicie jest obowiązkowe.<br>Dokończ rozpoczętą sekwencję.';
 setText('#move-total',String(history.length).padStart(2,'0'));const list=$('#history-list');const rounds=[];
 for(let i=0;i<history.length;i+=2){rounds.push(`<div class="score-row"><span>${String(i/2+1).padStart(2,'0')}</span><span title="${formatMove(history[i].move)}">${formatMove(history[i].move)}</span><span title="${history[i+1]?formatMove(history[i+1].move):''}">${history[i+1]?formatMove(history[i+1].move):'—'}</span></div>`);}
 list.innerHTML='<div class="score-head"><span>NR</span><span>BIAŁE</span><span>CZARNE</span></div>'+(rounds.length?rounds.slice(-6).join(''):'<div class="history-empty">Białe rozpoczynają partię.</div>');list.scrollTop=list.scrollHeight;

 if(!$('#keyboard-board').hidden)renderKeyboard();
}
function outcomeForUI(){return stepIndex?null:outcome(state);}
async function pick(i){
 if(!Number.isInteger(i)||i<0||i>63||busy||hinting||!humanTurn()||outcomeForUI())return;
 const steps=visibleSteps(),target=steps.find(s=>s.land===i);
 if(target){await playStep(target);return;}
 if(stepIndex>0){toast('Dokończ bicie tym samym pionem.');return;}
 if(state.board[i]*state.turn>0){const legal=legalTurns(state).filter(m=>m.from===i);if(!legal.length){toast(legalTurns(state)[0]?.captures?'Inny pion ma obowiązkowe bicie.':'Ten pion nie ma teraz wolnej drogi.');return;}selected=selected===i?null:i;choices=selected===null?[]:legal;render();sound();return;}
 if(selected!==null&&steps.some(s=>s.portal&&s.to===i)){toast('Kliknij wejście do portalu — mały znacznik na planszy.');return;}
 selected=null;choices=[];render();
}
async function playStep(step){
 const token=epoch;busy=true;if(!turnStart)turnStart=structuredClone(state);choices=choices.filter(m=>{const s=m.steps[stepIndex];return s&&s.land===step.land&&s.to===step.to&&s.capture===step.capture;});$('#undo-btn').disabled=true;$('#hint-btn').disabled=true;
 sound(step.portal?'portal':step.capture!==null?'capture':'move');await view.move(step);if(token!==epoch)return;state={...state,board:stepBoard(state.board,step)};stepIndex++;selected=step.to;
 if(choices.some(m=>m.steps.length>stepIndex)){busy=false;render();return;}
 const move=choices[0],before=turnStart;state=applyTurn(before,move);history.push({before,move});last=[move.from,move.steps.at(-1).to];selected=null;choices=[];stepIndex=0;turnStart=null;busy=false;render();afterTurn();
}
function afterTurn(){const result=outcome(state);if(result){setText('#result-title',result.winner===0?'Równowaga.':mode==='ai'?(result.winner===1?'Twoje zwycięstwo.':'Tym razem Nox.'):(result.winner===1?'Białe wygrywają.':'Czarne wygrywają.'));setText('#result-description',`${result.reason} Rozegrano ${history.length} tur.`);sound('win');$('#result-dialog').showModal();return;}if(state.variant==='eclipse'&&state.ply%8===0)toast('Nowa runda portali. Sprawdź połączone pola.');if(!humanTurn())runAI();}
function askAI(budget=850){return new Promise(resolve=>{const snapshot=structuredClone(state);let taskWorker,timer;const finish=move=>{clearTimeout(timer);taskWorker?.terminate();if(worker===taskWorker){worker=null;workerCancel=null;}resolve(move);};try{taskWorker=new Worker('./ai-worker.js',{type:'module'});worker=taskWorker;workerCancel=()=>finish(null);timer=setTimeout(()=>finish(legalTurns(snapshot)[0]),budget+2500);taskWorker.onmessage=({data})=>finish(data.error?legalTurns(snapshot)[0]:data.move);taskWorker.onerror=()=>finish(legalTurns(snapshot)[0]);taskWorker.postMessage({id:epoch,state:snapshot,level:hinting?'normal':level,budget});}catch{finish(chooseMove(snapshot,'normal',100));}});}
async function runAI(){const token=epoch;busy=true;render();const start=performance.now(),move=await askAI(level==='hard'?1200:700);if(token!==epoch||!move)return;await new Promise(r=>setTimeout(r,Math.max(0,650-(performance.now()-start))));if(token!==epoch)return;const before=structuredClone(state);for(const step of move.steps){sound(step.portal?'portal':step.capture!==null?'capture':'move');await view.move(step);if(token!==epoch)return;state={...state,board:stepBoard(state.board,step)};view.sync(state.board,portalPair(state));}state=applyTurn(before,move);history.push({before,move});last=[move.from,move.steps.at(-1).to];busy=false;render();afterTurn();}
function cancelJobs(){epoch++;workerCancel?.();worker?.terminate();worker=null;workerCancel=null;hinting=false;}
function startGame(options){cancelJobs();state=initialState(options.variant);mode=options.mode;level=options.level||'normal';selected=null;choices=[];stepIndex=0;turnStart=null;busy=false;history=[];last=[];document.querySelectorAll('dialog[open]').forEach(d=>d.close());render();toast(mode==='ai'?'Nowa partia. Białe zaczynają.':'Nowa partia dla dwóch osób. Białe zaczynają.');}
function undo(){if(busy&&!worker)return;if(!history.length&&!turnStart)return;cancelJobs();if(turnStart){state=turnStart;}else{let h=history.pop();state=h.before;if(mode==='ai'&&state.turn===-1&&history.length)state=history.pop().before;}selected=null;choices=[];stepIndex=0;turnStart=null;busy=false;last=history.length?[history.at(-1).move.from,history.at(-1).move.steps.at(-1).to]:[];$('#result-dialog').close();render();toast(mode==='ai'?'Cofnięto do Twojego ruchu.':'Cofnięto ostatni ruch.');}
async function hint(){if(busy||hinting||!humanTurn()||stepIndex||outcome(state))return;hinting=true;const token=epoch;render();const move=await askAI(600);if(token!==epoch)return;hinting=false;if(!move)return;selected=move.from;choices=legalTurns(state).filter(m=>m.from===selected);render();view.highlight(selected,[move.steps[0]],last);toast(`Spróbuj: ${formatMove(move)}`);}
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Pełny ekran jest niedostępny w tym podglądzie. Otwórz grę w osobnej karcie.');}}
function toggleCamera(){const top=view.cameraView();setText('#camera-label',top?'Widok z góry':'Widok 3D');}
function setSound(on){prefs.sound=on;$('#sound-setting').checked=on;$('#sound-btn').setAttribute('aria-label',on?'Wyłącz dźwięk':'Włącz dźwięk');$('#sound-btn').title=on?'Wyłącz dźwięk':'Włącz dźwięk';$('#sound-btn .icon').dataset.icon=on?'sound':'sound-off';icons($('#sound-btn'));savePrefs();if(on)sound();}
function renderKeyboard(){const board=$('#keyboard-board'),focused=document.activeElement?.dataset.square;board.innerHTML=state.board.map((p,i)=>{const legal=visibleSteps().some(s=>s.land===i),color=(i%8+(i>>3))%2===0?'light':'';return `<button type="button" data-square="${i}" class="${color} ${selected===i?'selected':''} ${legal?'legal':''}" aria-label="${coord(i)}, ${p?(p>0?'jasny':'ciemny')+' '+(Math.abs(p)===2?'damka':'pion'):'puste'}${legal?', możliwy ruch':''}"><span class="piece-char ${p>0?'white-piece':'black-piece'}">${p?iconMarkup(Math.abs(p)===2?'king':'checker'):''}</span><span class="coord">${coord(i)}</span></button>`;}).join('');if(focused)board.querySelector(`[data-square="${focused}"]`)?.focus();}
$('#keyboard-board').addEventListener('click',e=>{const b=e.target.closest('[data-square]');if(b)pick(+b.dataset.square);});$('#keyboard-toggle').onclick=()=>{$('#keyboard-board').hidden=!$('#keyboard-board').hidden;renderKeyboard();$('#keyboard-board button')?.focus();};$('#keyboard-board').addEventListener('keydown',e=>{const index=+e.target.closest('[data-square]')?.dataset.square;if(e.key==='Escape'){$('#keyboard-board').hidden=true;$('#keyboard-toggle').focus();return;}const delta={ArrowRight:1,ArrowLeft:-1,ArrowDown:8,ArrowUp:-8}[e.key];if(delta){e.preventDefault();$('#keyboard-board').querySelector(`[data-square="${Math.min(63,Math.max(0,index+delta))}"]`)?.focus();}});
for(const [btn,dialog] of [['rules-btn','rules-dialog'],['variant-info','rules-dialog'],['new-btn','new-dialog'],['settings-btn','settings-dialog']])$(`#${btn}`).onclick=()=>{$(`#${dialog}`).showModal();};
document.querySelectorAll('.close-dialog,.close-action').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('#new-form').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));startGame(values);};$('#new-form').addEventListener('change',()=>{$('#new-form select').disabled=new FormData($('#new-form')).get('mode')==='local';});$('#again-btn').onclick=()=>{$('#result-dialog').close();$('#new-dialog').showModal();};$('#undo-btn').onclick=undo;$('#hint-btn').onclick=hint;$('#camera-btn').onclick=toggleCamera;$('#reset-camera-btn').onclick=()=>{view.cameraView(false);setText('#camera-label','Widok 3D');};$('#fullscreen-btn').onclick=fullscreen;$('#sound-btn').onclick=()=>setSound(!prefs.sound);$('#sound-setting').onchange=e=>setSound(e.target.checked);$('#motion-setting').checked=prefs.motion;$('#quality-setting').checked=prefs.low;$('#motion-setting').onchange=e=>{prefs.motion=e.target.checked;view.reduced=prefs.motion;savePrefs();};$('#quality-setting').onchange=e=>{prefs.low=e.target.checked;view.quality(prefs.low);savePrefs();};
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||document.querySelector('dialog[open]')||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||e.target.closest('#keyboard-board'))return;const action={z:undo,h:hint,v:toggleCamera,f:fullscreen}[e.key.toLowerCase()];if(action){e.preventDefault();action();}});
try{view=new BoardView($('#viewport'),pick);view.reduced=prefs.motion;if(prefs.low)view.quality(true);$('#loading').remove();setSound(prefs.sound);render();$('#viewport').addEventListener('render-lost',()=>{toast('Utracono obraz 3D. Możesz dokończyć grę na planszy klawiaturowej.');$('#keyboard-board').hidden=false;renderKeyboard();});}catch(error){console.error(error);$('#loading').innerHTML='<span>Twoja przeglądarka nie uruchomiła widoku 3D.</span><span>Możesz zagrać na planszy poniżej.</span>';$('#loading').style.inset='0 0 auto';$('#loading').style.paddingTop='80px';view={sync(){},highlight(){},move:async()=>{},cameraView(){toast('Widok 3D jest niedostępny.');return false;},quality(){}};$('#keyboard-board').hidden=false;render();}
// Page tools use exactly the same actions and legality checks as the visible board.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 register({name:'eclipse_read_game',description:'Odczytaj bieżącą planszę i legalne wejścia ruchów.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({turn:state.turn,variant:state.variant,ply:state.ply,busy,board:state.board,portals:portalPair(state),moves:legalTurns(state).map(m=>({from:coord(m.from),land:coord(m.steps[0].land),notation:notation(m)}))})});
 register({name:'eclipse_play_step',description:'Wybierz pion i wykonaj legalny krok na planszy. Przy biciu wielokrotnym powtórz dla kolejnego kroku.',inputSchema:{type:'object',properties:{from:{type:'string',pattern:'^[A-H][1-8]$'},land:{type:'string',pattern:'^[A-H][1-8]$'}},required:['from','land'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(busy||hinting||!humanTurn()||outcomeForUI())throw new Error('Poczekaj na ruch gracza.');if(!input||!/^[A-H][1-8]$/.test(input.from)||!/^[A-H][1-8]$/.test(input.land))throw new Error('Nieprawidłowe współrzędne.');const from=(8-Number(input.from[1]))*8+input.from.charCodeAt(0)-65,land=(8-Number(input.land[1]))*8+input.land.charCodeAt(0)-65;const legal=stepIndex?choices:legalTurns(state).filter(m=>m.from===from);if(stepIndex&&from!==selected)throw new Error('Kontynuuj tym samym pionem.');if(!legal.some(m=>m.steps[stepIndex]?.land===land))throw new Error('Niedozwolony ruch.');if(!stepIndex){selected=from;choices=legal;}await pick(land);return {ply:state.ply,turn:state.turn,continueCapture:stepIndex>0};}});
}
